<script>
  import { onMount } from 'svelte'
  import { fetchAdminAudit } from '../../lib/api.js'
  export let data
  export let canViewAudit = true
  $: security = data?.device_security || {}
  $: risks = Number(security.users_over_limit || 0) + Number(security.awaiting_reimport || 0)
  let events=[];let auditError='';let auditLoading=true;let query='';let outcome='all'
  $: normalized=query.trim().toLocaleLowerCase('ru-RU')
  $: visibleEvents=events.filter(event=>(outcome==='all'||event.outcome===outcome)&&(!normalized||[event.action,event.actor_id,event.actor_type,event.target_type,event.target_id,event.outcome].some(value=>String(value||'').toLocaleLowerCase('ru-RU').includes(normalized))))
  async function loadAudit(){if(!canViewAudit){auditLoading=false;auditError='Недостаточно прав для просмотра аудита';return}auditLoading=true;auditError='';try{events=(await fetchAdminAudit(100)).events||[]}catch(error){auditError=error.code===403?'Недостаточно прав для просмотра аудита':`Аудит временно недоступен: ${error.reason||error.message}`}finally{auditLoading=false}}
  onMount(loadAudit)
  const stamp=value=>value?new Date(value).toLocaleString('ru-RU'):'—'
</script>

<section class="page">
  <header><div><span>КОНТРОЛЬ ДОСТУПА</span><h2>Безопасность</h2><p>Состояние привязок устройств и журнал административных действий.</p></div><strong class:danger={risks}>{risks ? `${risks} требуют внимания` : 'Нарушений нет'}</strong></header>
  <div class="metrics">
    <article><small>АКТИВНЫЕ УСТРОЙСТВА</small><b>{security.active_devices || 0}</b><p>Устройства, отмеченные активными в базе</p></article>
    <article><small>ОТОЗВАННЫЕ</small><b>{security.revoked_devices || 0}</b><p>Отозванные привязки устройств</p></article>
    <article><small>ЖЁСТКАЯ ПРИВЯЗКА</small><b>{security.protected_users || 0}</b><p>Пользователи с контролем device token</p></article>
    <article class:danger={security.users_over_limit}><small>СВЕРХ ЛИМИТА</small><b>{security.users_over_limit || 0}</b><p>Аккаунты с числом устройств выше лимита</p></article>
  </div>
  <section class="policy"><h3>Политика выдачи подписки</h3><div><i>1</i><span><b>Идентификация Happ</b><small>При поддерживаемом клиенте запрос сопоставляется с device token.</small></span></div><div><i>2</i><span><b>Отозванные устройства ограничиваются</b><small>Для отозванной привязки рабочий каталог не выдаётся.</small></span></div><div><i>3</i><span><b>Единый источник данных</b><small>Публичная выдача использует актуальную базу control-plane.</small></span></div></section>
  <section class="audit">
    <header><div><h3>Журнал административных действий</h3><p>Последние {events.length} событий, полученных от API.</p></div><button on:click={loadAudit} disabled={auditLoading||!canViewAudit}>{auditLoading?'Обновляем…':'Обновить'}</button></header>
    <div class="filters"><label><span>Поиск</span><input aria-label="Поиск в журнале аудита" bind:value={query} placeholder="Действие, актор или объект"/></label><label><span>Результат</span><select aria-label="Фильтр результата аудита" bind:value={outcome}><option value="all">Все результаты</option><option value="success">Успешно</option><option value="denied">Отклонено</option><option value="failed">Ошибка</option></select></label></div>
    {#if auditLoading}<p role="status">Загружаем журнал аудита…</p>{:else if auditError}<div class="state error" role="alert"><span>{auditError}</span>{#if canViewAudit}<button on:click={loadAudit}>Повторить</button>{/if}</div>{:else if !visibleEvents.length}<p>{events.length?'По выбранным условиям событий нет.':'Событий пока нет.'}</p>{:else}<div class="events">{#each visibleEvents as event}<article><span><b>{event.action}</b><small>{event.actor_id || event.actor_type || 'system'} · {event.target_type || 'system'}{event.target_id ? `/${event.target_id}` : ''}</small></span><em class:denied={event.outcome==='denied'||event.outcome==='failed'}>{event.outcome||'unknown'}</em><time datetime={event.created_at}>{stamp(event.created_at)}</time></article>{/each}</div>{/if}
  </section>
</section>

<style>
.page{display:grid;gap:18px;min-width:0}.page>header{display:flex;align-items:flex-end;justify-content:space-between;gap:18px}.page>header span{color:#80c9f4;font-size:10px;font-weight:900;letter-spacing:.15em}.page h2{margin:8px 0 5px;font-size:30px}.page p{margin:0;color:#7890a5}.page>header>strong{padding:10px 14px;border-radius:15px;background:rgba(97,216,165,.1);color:#78e1b4;font-size:11px;white-space:nowrap}.page>header>strong.danger{background:rgba(255,121,121,.1);color:#ff9c9c}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metrics article,.policy{border:1px solid rgba(155,217,255,.1);background:linear-gradient(145deg,#101b29,#0a121d)}.metrics article{padding:21px;border-radius:22px;min-width:0}.metrics small{color:#7890a5;font-size:9px;letter-spacing:.1em}.metrics b{display:block;margin:14px 0 8px;font-size:34px}.metrics p{font-size:11px;line-height:1.45}.metrics article.danger b{color:#ff9c9c}.policy{padding:24px;border-radius:24px}.policy h3{margin:0 0 18px}.policy>div{display:flex;align-items:center;gap:13px;padding:13px 0;border-top:1px solid rgba(155,217,255,.07)}.policy i{display:grid;flex:0 0 36px;width:36px;height:36px;place-items:center;border-radius:50%;background:#15314a;color:#9bd9ff;font-style:normal;font-weight:900}.policy span{display:flex;min-width:0;flex-direction:column;gap:4px}.policy small{color:#7890a5}.audit{padding:24px;border:1px solid rgba(155,217,255,.1);border-radius:24px;background:linear-gradient(145deg,#101b29,#0a121d)}.audit>header{display:flex;align-items:flex-start;justify-content:space-between;gap:15px;margin-bottom:14px}.audit h3{margin:0 0 5px}.audit>header button,.state button{min-height:39px;border:1px solid rgba(155,217,255,.16);border-radius:12px;padding:0 14px;background:#14283a;color:#bde7ff}.filters{display:grid;grid-template-columns:minmax(220px,1fr) 190px;gap:8px;margin-bottom:12px}.filters label{display:grid;gap:5px;padding:8px 11px;border-radius:12px;background:#0b1119}.filters label span{color:#6f879b;font-size:9px;font-weight:800}.filters input,.filters select{width:100%;border:0;outline:0;background:transparent;color:#eaf4fc}.filters option{background:#101b29}.audit p,.audit small{color:#7890a5}.events{display:grid}.audit article{display:grid;grid-template-columns:minmax(0,1fr) auto 160px;align-items:center;gap:14px;padding:12px 0;border-top:1px solid rgba(155,217,255,.07)}.audit article span{display:flex;min-width:0;flex-direction:column;gap:4px}.audit article b,.audit article small{overflow-wrap:anywhere}.audit em{color:#78e1b4;font-size:11px;font-style:normal}.audit em.denied{color:#ff9c9c}.audit time{color:#7890a5;font-size:11px;text-align:right}.state{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px;border-radius:13px;background:#14283a}.state.error{background:rgba(150,54,65,.15);color:#ffb1b6}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #9bd9ff;outline-offset:2px}button:disabled{cursor:not-allowed;opacity:.5}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}.audit article{grid-template-columns:minmax(0,1fr) auto}.audit time{grid-column:1/-1;text-align:left}}@media(max-width:520px){.page h2{font-size:25px}.page>header,.audit>header{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:1fr}.policy,.audit{padding:18px}.filters{grid-template-columns:1fr}.audit article{gap:8px}.page>header>strong{white-space:normal}}
</style>
